/**
 * Members of the active tenant, for pickers. Optional ?role= filter.
 */
export const getApiV1MembersListUrl = (params?: ApiV1MembersListParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/members/?${stringifiedParams}` : `/api/v1/members/`
}

